// Build the transport-NMA + registry-publication-bias manuscript .docx from verified
// committed numbers. Truth-first: every table value is transcribed from the committed
// transport_nma JSON artifacts (aact_kappa*.json, h2h_result.json, tnma_result); figures
// are regenerated by make_tnma_figures.py. Edit THIS file (not the .md) for the .docx.
// Run: node manuscript/build_tnma_docx.js
const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType, ShadingType,
  PageNumber, Footer, VerticalAlign,
} = require("docx");

const DIR = __dirname;
const FIG = path.join(DIR, "figures_tnma");

// ---------- helpers ----------
const border = { style: BorderStyle.SINGLE, size: 1, color: "BBBBBB" };
const borders = { top: border, bottom: border, left: border, right: border };
const cellMargins = { top: 60, bottom: 60, left: 110, right: 110 };
function runs(text, opts = {}) { return [new TextRun({ text, ...opts })]; }
function P(text, opts = {}) {
  return new Paragraph({ spacing: { after: opts.after ?? 120, line: 276 },
    alignment: opts.align, children: Array.isArray(text) ? text : runs(text, opts) });
}
function H1(text) { return new Paragraph({ heading: HeadingLevel.HEADING_1, children: runs(text) }); }
function H2(text) { return new Paragraph({ heading: HeadingLevel.HEADING_2, children: runs(text) }); }
function bullet(text) {
  return new Paragraph({ numbering: { reference: "bullets", level: 0 },
    spacing: { after: 60 }, children: Array.isArray(text) ? text : runs(text) });
}
function refItem(text) {
  return new Paragraph({ numbering: { reference: "refs", level: 0 },
    spacing: { after: 40 }, children: Array.isArray(text) ? text : runs(text, { size: 18 }) });
}
function tableFrom(headerRow, dataRows, colWidths) {
  const total = colWidths.reduce((a, b) => a + b, 0);
  const mkCell = (txt, w, opts = {}) => new TableCell({
    borders, width: { size: w, type: WidthType.DXA }, margins: cellMargins,
    verticalAlign: VerticalAlign.CENTER,
    shading: opts.head ? { fill: "D5E8F0", type: ShadingType.CLEAR }
      : (opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined),
    children: [new Paragraph({ spacing: { after: 0 },
      children: runs(String(txt), { bold: !!opts.head || !!opts.bold, size: 16 }) })],
  });
  const rows = [];
  rows.push(new TableRow({ tableHeader: true,
    children: headerRow.map((h, i) => mkCell(h, colWidths[i], { head: true })) }));
  for (const r of dataRows) {
    rows.push(new TableRow({ children: r.map((c, i) => {
      const v = (c && typeof c === "object") ? c : { t: c };
      return mkCell(v.t, colWidths[i], { bold: v.bold, fill: v.fill });
    }) }));
  }
  return new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: colWidths, rows });
}
function figure(file, caption, widthPx) {
  const data = fs.readFileSync(path.join(FIG, file));
  const w = data.readUInt32BE(16), h = data.readUInt32BE(20);
  const dispW = widthPx ?? 560;
  const dispH = Math.round(dispW * h / w);
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 60 },
      children: [new ImageRun({ type: "png", data, transformation: { width: dispW, height: dispH },
        altText: { title: caption, description: caption, name: file } })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 160 },
      children: runs(caption, { italics: true, size: 17 }) }),
  ];
}
function captionP(label, rest) {
  return new Paragraph({ spacing: { before: 60, after: 100 },
    children: [new TextRun({ text: label, bold: true, size: 18 }), new TextRun({ text: rest, size: 18 })] });
}
const B = (t) => new TextRun({ text: t, bold: true });
const T = (t) => new TextRun({ text: t });

// ---------- content ----------
const children = [];

// Title block
children.push(new Paragraph({ spacing: { after: 120 }, children: runs(
  "Registry-informed publication-bias correction for network meta-analysis: external effect-inflation magnitude from the ClinicalTrials.gov registered-versus-published gap",
  { bold: true, size: 28 }) }));
children.push(P([new TextRun({ text: "Mahmood Ahmad", bold: true }), new TextRun({ text: "¹²", superScript: true })], { after: 40 }));
children.push(P([new TextRun({ text: "¹ ", size: 18 }), new TextRun({ text: "Royal Free Hospital, London, United Kingdom", size: 18 })], { after: 20 }));
children.push(P([new TextRun({ text: "² ", size: 18 }), new TextRun({ text: "Tahir Heart Institute, Rabwah, Pakistan", size: 18 })], { after: 40 }));
children.push(P([new TextRun({ text: "ORCID: 0000-0001-9107-3704. Correspondence: mahmood726@gmail.com.", size: 18 })], { after: 80 }));
children.push(P([new TextRun({ text: "Competing interests. ", bold: true, size: 18 }),
  new TextRun({ text: "The author is an honorary member of the editorial board of Synthēsis (former Editor-in-Chief) and had no role in the handling, peer review, or editorial decision-making for this manuscript; any submission would be handled independently by another editor of the journal.", size: 18 })], { after: 40 }));
children.push(P([new TextRun({ text: "Funding. ", bold: true, size: 18 }), new TextRun({ text: "None.", size: 18 })], { after: 40 }));
children.push(P([new TextRun({ text: "Companion papers. ", bold: true, italics: true, size: 18 }),
  new TextRun({ text: "AdaptShrink (univariate) and AdaptShrink-NMA share the netmeta-parity engine used here; this paper addresses a distinct problem — publication-bias correction in NMA from an external registry signal rather than the in-network funnel.", size: 18, italics: true })], { after: 120 }));

// Abstract
children.push(H1("Abstract"));
children.push(P([B("Background. "), T("Funnel-based publication-bias corrections (Egger/PET-PEESE, trim-and-fill, Copas–Shi, Henmi–Copas) are unreliable in network meta-analysis (NMA), where each treatment rests on only a handful of direct comparisons. We ask whether an external registry signal can supply what the in-network funnel cannot.")]));
children.push(P([B("Methods. "), T("We correct a placebo-relative basic contrast dₜ by κ·(1−λₜ), where λₜ is the drug class's ClinicalTrials.gov results-reporting integrity (results-posted ÷ registered; AACT 2026-04-12) and κ is a selection-magnitude scale. On a real diabetes HbA1c network (metadat dat.senn2013; 10 treatments, 26 studies, τ = 0.33, I² = 1%) and a matched-coverage known-truth simulation on its geometry, we benchmark the registry correction against PET-PEESE, trim-and-fill, and Henmi–Copas. We then estimate κ externally — no oracle, no in-network funnel — from the AACT registered-versus-published HbA1c effect gap: within each class we compare mean absolute HbA1c mean-difference of trials whose results reached the literature (PubMed linkage) against trials with posted results but no linkage.")]));
children.push(P([B("Results. "), T("The external registry correction (oracle magnitude) is the only method that reliably improves matched-coverage error under selection (ΔMCIW0 −0.118 at B=0.15, −0.306 at B=0.30) and is exactly inert at B=0; every internal funnel model fails — PET-PEESE over-corrects catastrophically (up to +0.68 every cell). The registered-versus-published gap validates the registry model with no oracle: the per-class effect gap rises with selection severity (Pearson r = 0.50 vs 1−λ). The frozen pooled external magnitude κ = 0.158 matches the oracle at B=0.15 (ΔMCIW0 −0.119 vs −0.118) and wins across all B ≥ 0.15 in both funnel regimes — converting the correction from direction-only to direction + calibrated magnitude.")]));
children.push(P([B("Limitations (honest residual). "), T("A fixed external κ over-corrects modestly at true B=0 (ΔMCIW0 +0.05) — the selection-presence question, orthogonal to magnitude. A static class λ cannot certify a specific estimate is unbiased. We show, not assert, that this residual is irreducible on a sparse network: the only in-data presence gate (pooled-network Egger) fires ≤4% regardless of true B, so gating removes the B=0 harm but also every B>0 win. The correction is recommended where selection is a priori expected.")]));
children.push(P([B("Conclusion. "), T("An external registry signal supplies both the direction and, for the first time, a calibrated magnitude for publication-bias correction in a network too sparse for internal funnel methods.")], { after: 160 }));

// 1 Introduction
children.push(H1("1. Introduction"));
children.push(P("Publication and outcome-reporting bias inflates apparent treatment benefit; correcting for it is standard in pairwise meta-analysis but remains difficult in network meta-analysis (NMA). The established correctors — Egger's regression and its PET-PEESE refinement, the Duval–Tweedie trim-and-fill, and the Copas-family selection models — all read the funnel: they infer selection from the association between study effect and study precision. In an NMA that association must be estimated per contrast, and a typical contrast rests on three-to-six direct studies. A funnel regression on six points has ruinous intercept variance; a Copas selection model is simply infeasible."));
children.push(P("The information a sparse network lacks internally exists externally. Trial registries record which studies were run, independent of which were published. ClinicalTrials.gov, via the Aggregate Analysis of ClinicalTrials.gov (AACT) database, additionally records which registered trials posted structured results — a mandate strengthened by the FDAAA Final Rule — and, through automatic PubMed linkage, which trials' results reached the published literature. This is exactly the raw material of the classic registered-versus-published discrepancy studies (Turner 2008; Rising 2008), which showed that trials favourable to the sponsored drug are preferentially and more prominently published."));
children.push(P("This paper makes that external signal operational for NMA. We (i) define a per-class selection-severity proxy from the registry's results-reporting rate; (ii) benchmark a registry-informed correction head-to-head against the internal funnel models on a real diabetes network and a matched-coverage simulation; and (iii) — the main contribution — estimate the previously-missing selection magnitude externally, from the AACT registered-versus-published HbA1c effect gap, and show it recovers the correct correction strength with no oracle. We report the one place the approach cannot help (distinguishing a genuinely unbiased estimate within a selection-prone class) and demonstrate why that limit is irreducible on a sparse network."));

// 2 Methods
children.push(H1("2. Methods"));
children.push(H2("2.1 The network and the engine"));
children.push(P("We use the diabetes network dat.senn2013 from the metadat package (Senn 2013): 26 trials of oral glucose-lowering agents, outcome = mean change in HbA1c (%), connected through placebo and active comparators. Arms are reduced to study-level pairwise mean-difference contrasts and fitted with a frequentist graph-theoretic random-effects NMA (Rücker 2012); ranking uses the P-score (Rücker & Schwarzer 2015). The engine reproduces netmeta to ~1e-11. The fitted network has 10 treatments, 27 contrasts, τ = 0.33, I² = 1%, and reproduces the known ordering (rosiglitazone / pioglitazone / metformin most effective, sulfonylurea least)."));
children.push(H2("2.2 Registry selection-severity λ (direction)"));
children.push(P("For each drug class c we compute the results-reporting integrity ratio λc = (registered T2DM trials naming class c that posted results) ÷ (registered T2DM trials naming class c), from the AACT 2026-04-12 snapshot. A low λc means many trials of that class were registered but never posted results — a class-level fingerprint of reporting selection. We use (1 − λc) as the per-treatment selection-severity proxy. Observed values range from λ = 0.20 (α-glucosidase inhibitors) to λ = 0.48 (DPP-4 inhibitors)."));
children.push(H2("2.3 The correction"));
children.push(P("A placebo-relative basic contrast is shrunk toward the null in proportion to its class's severity: dₜ(corrected) = dₜ · (1 − κ·(1 − λₜ)), with an optional registry-informed variance inflation 1/√λₜ so the interval widens honestly for selection-prone classes. κ is the selection-magnitude scale, common across the network. The entire contribution of §2.5 is to estimate κ externally rather than assume it."));
children.push(H2("2.4 Truth-gate"));
children.push(P("We inject a known class-selection bias into each active treatment's true placebo-relative effect, dₜ(observed) = dₜ(true) · (1 + B·(1 − λₜ)), sweeping the unknown true strength B ∈ {0, 0.15, 0.263, 0.30}, and ask whether the correction recovers the true contrasts better than the unadjusted NMA. The metric is MCIW0 — twice the 95th percentile of |estimate − truth| across all (replicate × treatment) cells — with a paired bootstrap (3,000 resamples) CI on ΔMCIW0 vs the unadjusted baseline; a robust win requires the 97.5% CI upper limit below zero. Two selection geometries are scored: Regime A, a uniform multiplicative bias (SE-orthogonal, funnel-invisible), and Regime B, the same per-treatment magnitude distributed as a small-study effect (funnel-visible). Regime B is the geometry internal funnel methods are designed for; Regime A is the geometry registry selection actually produces."));
children.push(H2("2.5 External magnitude from the registered-versus-published gap"));
children.push(P("We estimate κ externally, with no oracle and no in-network funnel, using the logic of Turner (2008) inside the registry. Whether a trial's results reached the published literature is observable through PubMed linkage (study_references.reference_type ∈ {DERIVED, RESULT} → a PMID citing the trial's NCT number). We split each class's trials into published (a linkage exists) and registered-only (results posted, no linkage). If publication favours larger effects, the published subset should show a larger treatment effect."));
children.push(P("Endpoint and scale are held fixed to match the network: we extract HbA1c mean-difference analyses (outcome_analyses where param_type contains \"mean difference\"), normalise IFCC mmol/mol to NGSP % (a difference × 0.0915), and discard implausible |MD| > 5% (scale-coding errors). For each class c with adequate support we compute κ_MD(c) = mean|MD|_published ÷ mean|MD|_registered-only − 1. Two frozen, deployable summaries are formed before any simulation scoring: κ_pooled, the n-weighted mean of max(0, κ_MD(c)) over adequately-powered classes (a per-node effect-inflation scale), and κ_slope, the WLS slope of κ_MD(c) on (1 − λc) through the origin (an external estimate of B). Adequate support = min(n_published, n_registered-only) ≥ 8."));
children.push(H2("2.6 Software and reproducibility"));
children.push(P("All analyses are Python (NumPy/SciPy/pandas/DuckDB) on the committed netmeta-parity engine. Scripts: class_lambda.py (λ), aact_kappa.py → aact_kappa_freeze.py (external κ, frozen), tnma.py and h2h_bench.py (head-to-head), aact_kappa_truthgate.py (external-κ truth-gate). Regression tests in test_aact_kappa.py (4/4) guard the frozen numbers and the headline win. Every value in this manuscript is transcribed from a committed JSON artifact."));

// 3 Results
children.push(H1("3. Results"));
children.push(H2("3.1 The real network and correction"));
children.push(P("On dat.senn2013 the registry overlay shrinks each active treatment's apparent benefit in proportion to its class's severity (Table 1). Rosiglitazone's placebo-relative HbA1c effect moves from −1.23% to −0.88% (TZD, λ = 0.42); the α-glucosidase inhibitors move most (λ = 0.20). Benfluorex, which has no registered drug class, is left unadjusted (λ ≡ 1). This is the qualitative behaviour a registry correction should have; §3.3–3.5 test it quantitatively."));

children.push(captionP("Table 1. ", "Real dat.senn2013 network with the registry overlay (κ = 0.5 illustrative): MD vs placebo, SE, P-score, class, registry λ, registry-adjusted MD. Source: tnma.py / tnma_result.txt."));
